package com.workworth.earnings.application;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.workworth.earnings.domain.*; import com.workworth.earnings.persistence.*; import com.workworth.salary.domain.*; import com.workworth.workday.domain.*; import com.workworth.workday.persistence.*; import java.math.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.test.util.ReflectionTestUtils;
class EarningCorrectionServiceTest {WorkdayEarningRepository earnings=mock(WorkdayEarningRepository.class);EarningCorrectionRepository corrections=mock(EarningCorrectionRepository.class);WorkdayTimeCorrectionRepository workdayCorrections=mock(WorkdayTimeCorrectionRepository.class);Clock clock=Clock.fixed(Instant.parse("2026-01-02T10:00:00Z"),ZoneId.of("Europe/Madrid"));EarningCorrectionService service=new EarningCorrectionService(earnings,corrections,workdayCorrections,clock);
 WorkdayEarning base(){var e=new WorkdayEarning(1L,LocalDate.of(2026,1,1),EarningStatus.AVAILABLE,3600,new BigDecimal("10.000000000000"),1L,IncomeSource.NET_MONTHLY_REAL,new BigDecimal("1000"),new BigDecimal("12000"),12,"EUR",new BigDecimal("100"),new BigDecimal("10"),clock.instant());ReflectionTestUtils.setField(e,"id",5L);return e;}
 WorkdayTimeCorrection correction(Workday d,WorkdayTimeCorrectionCause cause,long seconds){var c=new WorkdayTimeCorrection(d,cause,3600,seconds,clock.instant());ReflectionTestUtils.setField(c,"id",9L);return c;}
 @Test void preservesSnapshotAndIsIdempotent(){var d=mock(Workday.class);when(d.getId()).thenReturn(1L);var b=base();when(earnings.findByWorkdayId(1L)).thenReturn(Optional.of(b));when(corrections.findByEarningIdOrderBySequenceDesc(5L)).thenReturn(List.of());when(corrections.save(any())).thenAnswer(x->x.getArgument(0));service.apply(correction(d,WorkdayTimeCorrectionCause.PARTIAL_ABSENCE_CHANGED,1800));verify(corrections).save(argThat(c->c.getPreviousCorrection()==null&&c.getNewAmount().compareTo(new BigDecimal("5.000000000000"))==0));when(corrections.existsByWorkdayTimeCorrectionId(9L)).thenReturn(true);service.apply(correction(d,WorkdayTimeCorrectionCause.PARTIAL_ABSENCE_CHANGED,1800));verify(corrections,times(1)).save(any());}
}
